 private int GREEN=Color.rgb(25,122,96),INK=Color.rgb(23,62,53),MUTED=Color.rgb(116,132,115),BG=Color.rgb(246,248,242),LIME=Color.rgb(214,237,170);private int SURFACE=Color.WHITE,SECONDARY=Color.rgb(232,239,221),SELECTED=Color.rgb(229,238,215);private boolean dark=false,offline=false;private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private SessionStore store;private LinearLayout root,content,nav;private TextView banner,live;private JSONObject user=null,office=null;private JSONArray employees=new JSONArray(),records=new JSONArray();private boolean initialized=true,busy=false,resumed=false,registered=false,formMode=false;private String view="Overview",employeeFilter="",csvEmployee="";private long synced=0;private Button trackingButton;private final List<Button> buttons=new ArrayList<>();
 private final Runnable refresh=new Runnable(){public void run(){if(!resumed)return;if(user!=null&&!busy){if("Overview".equals(view)||"Employees".equals(view)||"Attendance".equals(view))loadStats(false);}updateLive();main.postDelayed(this,15000);}};
 private final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(store.token().isEmpty()&&user!=null){user=null;loadStatus();}else{updateLive();if(user!=null&&!busy)loadStats(false);}}};
 interface Job{Object run() throws Exception;}interface Done{void accept(Object result) throws Exception;}
 @Override public void onCreate(Bundle b){setTheme(getSharedPreferences("geo_private",MODE_PRIVATE).getBoolean("darkMode",false)?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);super.onCreate(b);if(b!=null)view=b.getString("currentView","Overview");store=new SessionStore(this);applyPalette();getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);loadStatus();}
