 @Override public void onResume(){super.onResume();resumed=true;if(!registered){if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,new IntentFilter(AttendanceService.CHANGED),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,new IntentFilter(AttendanceService.CHANGED));registered=true;}main.removeCallbacks(refresh);main.postDelayed(refresh,15000);if(user!=null){loadStats(false);if(isEmployee()&&store.prefs().getBoolean("trackingWanted",false)&&!AttendanceService.running&&fine())startServiceVisible();}updateLive();}
